        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "好嘞。林岚，其实你心里还是在乎这广播站的，只是嘴上不承认，对吧？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "胶带拉紧点，别留缝隙，进水还得重来。"
        }
